export function retryLocation(url) {
  const u = new URL(url);
  if (u.searchParams.has('ewresponse'))
    throw Error('Never append a second retry marker');
  // Read raw search; do not round-trip original parameters through URLSearchParams.
  return (
    u.pathname +
    u.search +
    (u.search ? (u.search.endsWith('&') ? '' : '&') : '?') +
    'ewresponse=retry'
  );
}

const data = verify(req.headers.get('x-demo-child') || '');
if (!data || !validRun(data.run))
  return json({ error: 'untrusted child marker' }, 401);
if (data.depth !== 1)
  return json({ error: 'depth limit: exactly one child level' }, 409);
const receipt = await event(
  data.run,
  'child',
  { parentId: data.parentId, depth: 1 },
  data.childId,
);
return json({
  mock: 'owned child; no further fetch',
  run: data.run,
  parentId: data.parentId,
  childId: data.childId,
  depth: 1,
  ...receipt,
});

